<?php
declare(strict_types=1);
function audit_request_id():string{if(empty($GLOBALS["audit_request_id"])){$c=trim((string)($_SERVER["HTTP_X_REQUEST_ID"]??""));if(!preg_match("/^[A-Za-z0-9._-]{8,80}$/",$c))$c=bin2hex(random_bytes(16));$GLOBALS["audit_request_id"]=$c;}return $GLOBALS["audit_request_id"]; }
function audit_source_ip():string{$ip=trim((string)($_SERVER["REMOTE_ADDR"]??""));return filter_var($ip,FILTER_VALIDATE_IP)?$ip:"";}
function audit_sanitize(?string $v,int $max=500):string{$v=(string)($v??"");$v=str_replace(["\r","\n","\t","\0"],["\\r","\\n","\\t",""] ,$v);return mb_substr($v,0,$max);}
function audit_log_key(array $config):?string{static $key=null,$ready=false;if($ready)return $key;$ready=true;try{$path=$config["storage_path"].DIRECTORY_SEPARATOR.".audit-key";if(!is_file($path)&&@file_put_contents($path,base64_encode(random_bytes(32)),LOCK_EX)!==false)@chmod($path,0600);$raw=@file_get_contents($path);if(is_string($raw)&&strlen(trim($raw))>=40)$key=trim($raw);}catch(Throwable $e){error_log("Portal audit key error: ".$e->getMessage());}return $key;}
function audit_canonical(array $row):string{unset($row["id"],$row["event_hash"]);return json_encode($row,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_LINE_TERMINATORS|JSON_THROW_ON_ERROR);}
function audit_meta_get(PDO $db,string $key,string $default):string{$s=$db->prepare("SELECT value FROM audit_meta WHERE key=? LIMIT 1");$s->execute([$key]);$v=$s->fetchColumn();return is_string($v)?$v:$default;}
function audit_meta_set(PDO $db,string $key,string $value):void{$s=$db->prepare("INSERT INTO audit_meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value");$s->execute([$key,$value]);}
function audit_event(PDO $unused,array $config,string $eventType,string $severity="INFO",bool $security=true,string $outcome="success",?string $actorType=null,?string $actorId=null,?string $message=null,array $metadata=[],?string $targetType=null,?string $targetId=null):void{try{$db=log_db($config);$severity=strtoupper($severity);if(!in_array($severity,["DEBUG","INFO","NOTICE","WARNING","ERROR","CRITICAL"],true))$severity="INFO";$outcome=in_array($outcome,["success","failure","blocked","error"],true)?$outcome:"success";$actorType=$actorType?:(admin_logged_in()?"admin":"anonymous");$actorId=$actorId!==null?audit_sanitize($actorId,120):(!empty($_SESSION["admin_username"])?audit_sanitize((string)$_SESSION["admin_username"],120):null);$path=audit_sanitize(parse_url((string)($_SERVER["REQUEST_URI"]??""),PHP_URL_PATH)?:"",500);$method=audit_sanitize((string)($_SERVER["REQUEST_METHOD"]??""),20);$ip=audit_source_ip();$rid=audit_request_id();$time=(new DateTimeImmutable("now",new DateTimeZone("UTC")))->format("Y-m-d\\TH:i:s.v\\Z");$meta=[];foreach($metadata as $k=>$v){if(preg_match("/pass(word)?|secret|token|pin|authorization|cookie|session|key/i",(string)$k))continue;if(is_scalar($v)||$v===null)$meta[audit_sanitize((string)$k,80)]=is_string($v)?audit_sanitize($v,500):$v;}$db->exec("BEGIN IMMEDIATE");$last=$db->query("SELECT event_hash FROM audit_logs ORDER BY id DESC LIMIT 1")->fetchColumn();$anchor=audit_meta_get($db,"chain_anchor",str_repeat("0",64));$prev=is_string($last)?$last:(preg_match("/^[a-f0-9]{64}$/",$anchor)?$anchor:str_repeat("0",64));$row=["event_time"=>$time,"app_version"=>(string)($config["version"]??""),"request_id"=>$rid,"severity"=>$severity,"security_event"=>$security?1:0,"event_type"=>audit_sanitize($eventType,100),"outcome"=>$outcome,"actor_type"=>audit_sanitize($actorType,40),"actor_id"=>$actorId,"source_ip"=>$ip,"method"=>$method,"path"=>$path,"target_type"=>$targetType!==null?audit_sanitize($targetType,60):null,"target_id"=>$targetId!==null?audit_sanitize($targetId,120):null,"message"=>audit_sanitize($message??$eventType,500),"metadata_json"=>$meta?json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):null,"prev_hash"=>$prev,"event_hash"=>""]; $key=audit_log_key($config);$row["event_hash"]=$key?hash_hmac("sha256",$prev.audit_canonical($row),$key):hash("sha256",$prev.audit_canonical($row));$s=$db->prepare("INSERT INTO audit_logs(event_time,app_version,request_id,severity,security_event,event_type,outcome,actor_type,actor_id,source_ip,method,path,target_type,target_id,message,metadata_json,prev_hash,event_hash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$s->execute([$row["event_time"],$row["app_version"],$row["request_id"],$row["severity"],$row["security_event"],$row["event_type"],$row["outcome"],$row["actor_type"],$row["actor_id"],$row["source_ip"],$row["method"],$row["path"],$row["target_type"],$row["target_id"],$row["message"],$row["metadata_json"],$row["prev_hash"],$row["event_hash"]]);$db->commit();}catch(Throwable $e){try{if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();}catch(Throwable $ignored){}error_log("Portal audit logging failed: ".$e->getMessage());}}
function audit_verify_chain(PDO $unused,array $config,int $limit=100000):array{$errors=[];$count=0;try{$db=log_db($config);$anchor=audit_meta_get($db,"chain_anchor",str_repeat("0",64));$prev=preg_match("/^[a-f0-9]{64}$/",$anchor)?$anchor:str_repeat("0",64);$key=audit_log_key($config);$st=$db->query("SELECT * FROM audit_logs ORDER BY id ASC LIMIT ".max(1,min($limit,100000)));while($row=$st->fetch(PDO::FETCH_ASSOC)){++$count;if(!hash_equals($prev,(string)$row["prev_hash"])){$errors[]="Cadena rota en evento #".(int)$row["id"];break;}$expected=$key?hash_hmac("sha256",$row["prev_hash"].audit_canonical($row),$key):hash("sha256",$row["prev_hash"].audit_canonical($row));if(!hash_equals($expected,(string)$row["event_hash"])){$errors[]="Hash inválido en evento #".(int)$row["id"];break;}$prev=$row["event_hash"];}}catch(Throwable $e){$errors[]="No se pudo verificar el registro: ".audit_sanitize($e->getMessage(),220);}return ["ok"=>!$errors,"count"=>$count,"errors"=>$errors];}
function audit_prune(PDO $unused,array $config):void{try{$db=log_db($config);$days=max(1,(int)($config["logs_retention_days"]??180));$max=max(1000,min((int)($config["logs_max_events"]??100000),500000));$db->exec("BEGIN IMMEDIATE");$st=$db->prepare("SELECT event_hash FROM audit_logs WHERE event_time < datetime('now', ?) ORDER BY id DESC LIMIT 1");$st->execute(["-{$days} days"]);$anchor=$st->fetchColumn();if(is_string($anchor)&&preg_match("/^[a-f0-9]{64}$/",$anchor)){$db->prepare("DELETE FROM audit_logs WHERE event_time < datetime('now', ?)")->execute(["-{$days} days"]);audit_meta_set($db,"chain_anchor",$anchor);} $count=(int)$db->query("SELECT COUNT(*) FROM audit_logs")->fetchColumn();if($count>$max){$extra=$count-$max;$st=$db->query("SELECT event_hash FROM audit_logs ORDER BY id ASC LIMIT ".(int)$extra);$hashes=$st->fetchAll(PDO::FETCH_COLUMN);$last=$hashes?$hashes[count($hashes)-1]:null;if(is_string($last)){$db->exec("DELETE FROM audit_logs WHERE id IN (SELECT id FROM audit_logs ORDER BY id ASC LIMIT ".(int)$extra.")");audit_meta_set($db,"chain_anchor",$last);}}$db->commit();}catch(Throwable $e){try{if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();}catch(Throwable $ignored){}error_log("Portal audit prune failed: ".$e->getMessage());}}
